import XCTest
import Foundation
@testable import MakoshTelegram

final class TelegramCustomEmojiAnimationDecoderTests: XCTestCase {
    private let tgs = Data(base64Encoded: "")!
    // Catches first-frame flattening, wrong channels and lost transparency along
    // the actual gzip → JSON → native vector → owned Swift frame path.
    func testGzippedTGSProducesDistinctPremultipliedFrames() async throws {
        guard let decoder = try? TelegramCustomEmojiAnimationDecoder(bytes: tgs, format: .tgs) else {
            XCTFail("A valid bounded TGS must construct the native decoder"); return
        }
        XCTAssertEqual(decoder.info.width, 4); XCTAssertEqual(decoder.info.height, 2)
        XCTAssertEqual(decoder.info.frameDurations, [0.5, 0.5])
        let first = try await decoder.frame(index: 0, width: 4, height: 2)
        let second = try await decoder.frame(index: 1, width: 4, height: 2)
        XCTAssertEqual(first.pixels.count, 32); XCTAssertEqual(second.pixels.count, 32)
        XCTAssertEqual(Array(first.pixels[0..<4]), [0, 0, 255, 255])
        XCTAssertEqual(Array(second.pixels[0..<4]), [0, 255, 0, 255])
        XCTAssertEqual(Array(first.pixels[12..<16]), [0, 0, 0, 0])
    }
    // Catches a vector preflight which silently selects one duplicate key while
    // the native parser consumes another, including escaped spellings.
    func testTGSRejectsDuplicateDecodedObjectKeysWithoutMergingSeparateScopes() throws {
        for text in [
            #"{"v":"5.5.7","w":512,"w":4,"h":2,"fr":2,"ip":0,"op":2,"layers":[]}"#,
            #"{"v":"5.5.7","w":4,"\u0077":4,"h":2,"fr":2,"ip":0,"op":2,"layers":[]}"#,
            #"{"v":"5.5.7","w":4,"h":2,"fr":2,"ip":0,"op":2,"assets":[{"id":"a","\u0069d":"b"}],"layers":[]}"#
        ] {
            XCTAssertThrowsError(try TelegramCustomEmojiAnimationDecoder(bytes: Data(text.utf8), format: .tgs))
        }
        let separate = Data(#"{"v":"5.5.7","w":4,"h":2,"fr":2,"ip":0,"op":2,"assets":[{"id":"a","layers":[]},{"id":"b","layers":[]}],"nm":"a \\\"quoted\\\" {key}: value","layers":[]}"#.utf8)
        let decoder = try TelegramCustomEmojiAnimationDecoder(bytes: separate, format: .tgs)
        XCTAssertEqual(decoder.info.frameCount, 2)
    }
    // Catches Foundation checking "w" while the native C-string comparison
    // aliases a different decoded key to "w" and accepts another canvas size.
    func testTGSRejectsNULInsideDecodedObjectKeys() {
        let ambiguous = Data(#"{"v":"5.5.7","w":4,"w\u0000ignored":8,"h":2,"fr":2,"ip":0,"op":2,"layers":[]}"#.utf8)
        XCTAssertThrowsError(try TelegramCustomEmojiAnimationDecoder(bytes: ambiguous, format: .tgs))
    }
    // Catches a static WebP-only path, incorrect per-frame delays or an opaque
    // bitmap conversion. Expected pixels come from the owned fixture recipe.
    func testAnimatedWebPKeepsBothFramesDelaysAndAlpha() async throws {
        guard let decoder = try? TelegramCustomEmojiAnimationDecoder(bytes: UploadWebPFixture.animated.data, format: .webP) else {
            XCTFail("A valid animated WebP must construct the native decoder"); return
        }
        XCTAssertEqual(decoder.info.width, 320); XCTAssertEqual(decoder.info.height, 160)
        XCTAssertEqual(decoder.info.frameCount, 2)
        guard decoder.info.frameCount == 2 else { return }
        XCTAssertEqual(decoder.info.frameDurations[0], 0.1, accuracy: 0.00001)
        XCTAssertEqual(decoder.info.frameDurations[1], 0.2, accuracy: 0.00001)
        let first = try await decoder.frame(index: 0, width: 320, height: 160)
        let second = try await decoder.frame(index: 1, width: 320, height: 160)
        let quadrant = (20 * 320 + 40) * 4, center = (80 * 320 + 160) * 4
        XCTAssertEqual(Array(first.pixels[quadrant..<quadrant+4]), [0, 0, 255, 255])
        XCTAssertEqual(Array(second.pixels[quadrant..<quadrant+4]), [255, 255, 0, 255])
        XCTAssertEqual(first.pixels[center+3], 0); XCTAssertEqual(second.pixels[center+3], 255)
    }
    // Catches corrupt/overexpanding gzip reaching the native parser, external
    // assets silently disappearing, and nonfinite/oversized vector metadata.
    func testTGSMalformedBoundedInputAndExternalAssetsFailClosed() {
        let bomb = Data(base64Encoded: "")!
        for bytes in [Data(tgs.dropLast()), Data([0x1f, 0x8b, 0]), bomb,
            Data(#"{"w":512,"h":512,"fr":30,"ip":0,"op":30,"assets":[{"id":"image","p":"private.png","u":"file:///"}],"layers":[]}"#.utf8),
            Data(#"{"w":true,"h":2,"fr":2,"ip":0,"op":2,"assets":[],"layers":[]}"#.utf8),
            Data(#"{"w":1537,"h":2,"fr":2,"ip":0,"op":2,"assets":[],"layers":[]}"#.utf8),
            Data(#"{"w":4,"h":2,"fr":0,"ip":0,"op":2,"assets":[],"layers":[]}"#.utf8)] {
            XCTAssertThrowsError(try TelegramCustomEmojiAnimationDecoder(bytes: bytes, format: .tgs))
        }
    }
    // Catches unchecked frame indexes or caller dimensions escaping the renderer
    // and a cancelled worker still producing a publishable frame.
    func testFrameBoundsAndCancellationCannotProducePixels() async throws {
        guard let decoder = try? TelegramCustomEmojiAnimationDecoder(bytes: tgs, format: .tgs) else {
            XCTFail("A valid bounded TGS must construct the native decoder"); return
        }
        for (index, width, height) in [(-1, 4, 2), (2, 4, 2), (0, 0, 2), (0, 513, 2), (0, 4, 513)] {
            do { _ = try await decoder.frame(index: index, width: width, height: height); XCTFail("Invalid render accepted") }
            catch { }
        }
        let (barrier, release) = AsyncStream<Void>.makeStream()
        let task = Task {
            for await _ in barrier { break }
            return try await decoder.frame(index: 0, width: 4, height: 2)
        }
        task.cancel(); release.finish()
        do { _ = try await task.value; XCTFail("Cancelled render accepted") } catch { }
    }
}
